# Exact ChainHawk brand mark supplied by the user, embedded so the script is portable.
CHAINHAWK_LOGO_B64 = """

"""

def load_chainhawk_logo(size=None, alpha=255):
    raw = base64.b64decode(CHAINHAWK_LOGO_B64)
    img = Image.open(io.BytesIO(raw)).convert("RGBA")
    if size:
        img.thumbnail((size, size), Image.LANCZOS)
    if alpha != 255:
        a = img.getchannel("A").point(lambda v: int(v * alpha / 255))
        img.putalpha(a)
    return img

def draw_hawk_logo(canvas, cx, cy, size, alpha=255):
    """Render the exact ChainHawk logo supplied by the user."""
    image = load_chainhawk_logo(int(size), alpha=alpha)
    photo = ImageTk.PhotoImage(image)
    canvas.delete("chainhawk_logo")
    canvas.create_image(cx, cy, image=photo, anchor="center", tags="chainhawk_logo")
    canvas._chainhawk_logo_ref = photo
    return photo



