def apply_app_icon(window):
    """Set the exact ChainHawk brand mark as the Tk window icon."""
    try:
        icon = tk.PhotoImage(data=APP_ICON_B64)
        window.iconphoto(False, icon)
        window._icon_ref = icon  # keep a reference so it isn't garbage-collected
    except tk.TclError:
        pass  # non-fatal if the platform/theme rejects it


