def _hex_to_rgb(hex_color):
    hex_color = hex_color.lstrip("#")
    return tuple(int(hex_color[i:i + 2], 16) for i in (0, 2, 4))


def _rgb_to_hex(rgb):
    return "#%02x%02x%02x" % tuple(max(0, min(255, int(c))) for c in rgb)


def draw_vertical_gradient(canvas, width, height, top_hex, bottom_hex):
    """Fill a canvas with a smooth vertical gradient (many thin bands),
    the simplest way to fake depth/atmosphere behind a card in Tkinter."""
    top_rgb = _hex_to_rgb(top_hex)
    bottom_rgb = _hex_to_rgb(bottom_hex)
    steps = max(height, 1)
    for i in range(steps):
        t = i / steps
        rgb = [top_rgb[c] + (bottom_rgb[c] - top_rgb[c]) * t for c in range(3)]
        canvas.create_line(0, i, width, i, fill=_rgb_to_hex(rgb))


def rounded_rect_points(x1, y1, x2, y2, r):
    """Point list approximating a rounded rectangle, for use with
    canvas.create_polygon(points, smooth=True, ...)."""
    return [
        x1 + r, y1,
        x2 - r, y1,
        x2, y1,
        x2, y1 + r,
        x2, y2 - r,
        x2, y2,
        x2 - r, y2,
        x1 + r, y2,
        x1, y2,
        x1, y2 - r,
        x1, y1 + r,
        x1, y1,
    ]


def draw_card_with_shadow(canvas, x1, y1, x2, y2, radius=18, fill=None, outline=None, shadow_offset=8):
    """Draws a soft drop-shadow rounded rectangle behind a lighter
    rounded-rectangle 'card' - the classic flat-design trick for making
    a panel look like it's floating above the background."""
    fill = fill or THEME["bg_panel"]
    outline = outline or THEME["accent_cyan"]
    # shadow (drawn first, so the card renders on top of it)
    canvas.create_polygon(
        rounded_rect_points(x1 + shadow_offset, y1 + shadow_offset, x2 + shadow_offset, y2 + shadow_offset, radius),
        smooth=True, fill="#000000", outline="",
    )
    # the card itself
    canvas.create_polygon(
        rounded_rect_points(x1, y1, x2, y2, radius),
        smooth=True, fill=fill, outline=outline, width=1,
    )


