# ---------------------------------------------------------------------
# 7. AUTHENTICATION + DATABASE (SQLite, hashed passwords)
# ---------------------------------------------------------------------
def init_db():
    """Create the users table if it doesn't exist yet. Safe to call every run."""
    conn = sqlite3.connect(DB_PATH)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            salt TEXT NOT NULL,
            password_hash TEXT NOT NULL
        )
    """)
    conn.commit()
    conn.close()


def hash_password(password: str, salt: bytes = None) -> tuple:
    """
    Never store plain-text passwords. This uses PBKDF2 (100,000 rounds
    of SHA-256) with a random per-user salt, which is the standard
    approach for password storage - even if someone steals the database
    file, they can't easily recover the original passwords.
    """
    if salt is None:
        salt = secrets.token_bytes(16)
    pwd_hash = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt, 100_000)
    return salt.hex(), pwd_hash.hex()


def verify_password(password: str, salt_hex: str, expected_hash_hex: str) -> bool:
    salt = bytes.fromhex(salt_hex)
    _, computed_hash_hex = hash_password(password, salt)
    # compare_digest avoids leaking timing information about how much
    # of the hash matched - a small but genuine security detail
    return secrets.compare_digest(computed_hash_hex, expected_hash_hex)


def create_user(username: str, password: str) -> tuple:
    """Returns (success: bool, message: str)."""
    init_db()
    salt_hex, hash_hex = hash_password(password)
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute(
            "INSERT INTO users (username, salt, password_hash) VALUES (?, ?, ?)",
            (username, salt_hex, hash_hex),
        )
        conn.commit()
        return True, "Account created. You can log in now."
    except sqlite3.IntegrityError:
        return False, "That username is already taken."
    finally:
        conn.close()


def authenticate_user(username: str, password: str) -> bool:
    init_db()
    conn = sqlite3.connect(DB_PATH)
    row = conn.execute(
        "SELECT salt, password_hash FROM users WHERE username = ?", (username,)
    ).fetchone()
    conn.close()
    if not row:
        return False
    salt_hex, hash_hex = row
    return verify_password(password, salt_hex, hash_hex)


def generate_random_password(length: int = 14) -> str:
    """Random password generator required by the project doc, using
    Python's `secrets` module (cryptographically secure, unlike `random`)."""
    alphabet = string.ascii_letters + string.digits + "!@#$%^&*"
    return "".join(secrets.choice(alphabet) for _ in range(length))


INTRO_VIDEO_PATH = "intro.webp"  # animated WEBP, NOT gif - gif's 256-color
                                  # palette is exactly what caused the
                                  # banded/low-quality look; WEBP keeps
                                  # full color depth and loads faster
INTRO_LOGO_PATH = None  # legacy external logo disabled; ChainHawk uses the embedded brand mark everywhere.


class RootApp(tk.Tk):
    """The ONE persistent root window for the entire application's
    lifetime. Every screen (intro video, logo, typed title, login,
    main dashboard) is a Frame swapped in and out of this single root,
    instead of each screen being its own separate tk.Tk() instance.

    This matters: destroying one tk.Tk() and creating a new one causes
    a real, visible flash to whatever's behind the app (e.g. your
    IDE), because each Tk() call tears down and rebuilds the entire
    native window at the OS level. A single persistent root with
    content swapped inside it never does that - there's exactly one
    native window for the whole program, so there's nothing to flash to.
    """

    def __init__(self):
        super().__init__()
        # Prevent Tk's native default window (which can briefly appear as a
        # blank/white window on Windows) from being shown before the first
        # ChainHawk screen has been completely constructed.
        # Keep the native window completely invisible while Tk/Windows
        # negotiates its initial window state.  On Windows, withdrawing a
        # Tk root and then immediately switching it to fullscreen can cause
        # one frame of the normal white client window to be painted.
        # Starting at alpha=0 prevents that native frame from ever becoming
        # visible to the user.
        # IMPORTANT: keep one normal Windows-native window for the entire
        # application lifetime.  We do NOT toggle fullscreen/normal between
        # intro, login and dashboard; that transition was the source of the
        # repeated white/purple window flashes on Windows.
        # IMPORTANT: do not withdraw, change alpha, or toggle fullscreen/zoom
        # during startup. On Windows those WM state transitions can produce
        # visible white/purple frames (and in some configurations can leave
        # the window invisible). Tk maps the root when mainloop starts, so we
        # prepare its final geometry first and show it only once.
        self.title(APP_NAME)
        apply_app_icon(self)
        self.configure(bg=THEME["bg"])
        self.resizable(True, True)
        try:
            sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
            # Leave the Windows taskbar/title-bar room; this is visually
            # equivalent to a maximized application without a maximize-state
            # transition during startup.
            self.geometry(f"{max(1100, sw-20)}x{max(700, sh-80)}+0+0")
        except tk.TclError:
            self.geometry("1400x850+0+0")
        self._current = None

    def show(self, frame_cls, **kwargs):
        """Destroys whatever screen is currently showing and replaces
        it with a new one, in this same window."""
        if self._current is not None:
            self._current.destroy()
        frame = frame_cls(self, **kwargs)
        frame.pack(fill="both", expand=True)
        self._current = frame
        # No deiconify/alpha/state transition here. The root is already
        # prepared with its final geometry; Tk paints this frame normally
        # when mainloop starts. Subsequent screens only replace child frames.
        self.update_idletasks()
        self.lift()
        self.focus_force()
        frame.focus_set()  # so the new screen's key bindings receive events
        return frame

    def set_fullscreen(self, on):
        self.attributes("-fullscreen", bool(on))

    def size_and_center(self, width, height, min_width=None, min_height=None):
        self.set_fullscreen(False)
        self.state("normal")
        self.resizable(True, True)
        self.minsize(min_width or 700, min_height or 600)
        self.update_idletasks()
        sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
        width = min(width, max(700, sw - 80))
        height = min(height, max(600, sh - 100))
        x, y = max(0, (sw - width) // 2), max(0, (sh - height) // 2)
        self.geometry(f"{width}x{height}+{x}+{y}")
        self.lift()
        self.focus_force()

    def close_app(self):
        try:
            if self._current is not None and hasattr(self._current, "shutdown"):
                self._current.shutdown()
        finally:
            self.destroy()


def make_fullscreen(root):
    root.attributes("-fullscreen", True)
    root.configure(bg=THEME["bg"])
    root.bind("<Escape>", lambda e: root.close_app())


class IntroVideoScreen(tk.Frame):
    """Intro screen: plays the branded intro clip (intro.webp, a
    lightweight animated-WEBP frame-sequence exported from the source
    video - Tkinter can't decode MP4 directly, and pulling in a full
    video-decoding library like OpenCV just for a silent intro isn't
    worth the dependency weight, so the video is pre-converted once
    and played back with Pillow, which the project already depends on).
    WEBP (not GIF) keeps full color depth - GIF's 256-color palette is
    what caused visible banding/low quality in an earlier version.

    NOTE: the source clip may have audio, but this only plays the
    picture - Tkinter has no audio decoding either. If audio matters,
    that needs a heavier dependency (e.g. python-vlc, which also
    requires VLC itself installed on whatever machine runs this).
    """

    FPS = 12  # must match the fps used when the intro.webp was generated

    def __init__(self, master, on_done):
        super().__init__(master, bg=THEME["bg"])
        self.on_done = on_done
        self._advanced = False
        self._add_intro_controls(self._advance)

        self.label = tk.Label(self, bg=THEME["bg"], bd=0, highlightthickness=0)
        self.label.pack(fill="both", expand=True)

        tk.Label(self, text="click, press Enter, or press Esc to skip", bg=THEME["bg"],
                 fg=THEME["fg_dim"], font=("Consolas", 11)).place(relx=0.5, rely=0.97, anchor="s")

        self.bind("<Button-1>", lambda e: self._advance())
        self.bind("<Return>", lambda e: self._advance())
        self.bind("<Escape>", lambda e: self._advance())

        self._frames = []
        self._delay_ms = max(20, round(1000 / self.FPS))
        if os.path.exists(INTRO_VIDEO_PATH):
            try:
                self._load_frames()
            except Exception as e:
                print(f"[intro] could not load {INTRO_VIDEO_PATH}: {e}")
                self.after(10, self._advance)
                return
        else:
            print(f"[intro] {INTRO_VIDEO_PATH} not found next to the script - skipping intro video.")
            self.after(10, self._advance)
            return

        self._frame_idx = 0
        self._play_frame()


    def _add_intro_controls(self, skip_command):
        bar = tk.Frame(self, bg=THEME["bg_panel"], bd=0)
        bar.place(relx=1.0, x=-18, y=18, anchor="ne")
        tk.Button(bar, text="SKIP", command=skip_command,
                  bg=THEME["bg_panel"], fg=THEME["accent_cyan"],
                  activebackground=THEME["accent_cyan"], activeforeground=THEME["bg"],
                  font=("Consolas", 10, "bold"), relief="solid", bd=1,
                  padx=12, pady=5, cursor="hand2").pack(side="left", padx=(0, 6))
        tk.Button(bar, text="EXIT APP", command=self.master.close_app,
                  bg=THEME["bg_panel"], fg=THEME["accent_red"],
                  activebackground=THEME["accent_red"], activeforeground=THEME["bg"],
                  font=("Consolas", 10, "bold"), relief="solid", bd=1,
                  padx=12, pady=5, cursor="hand2").pack(side="left")

    def _load_frames(self):
        sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
        img = Image.open(INTRO_VIDEO_PATH)
        for frame in ImageSequence.Iterator(img):
            frame = frame.convert("RGB")
            # Scale to fill height while preserving aspect ratio, letterboxed
            # on the theme background. NOTE: the source clip is 684x380 -
            # scaling that up to fill a large monitor's height will look
            # softer than a native high-res clip would; LANCZOS (used here)
            # is the best resampling filter for this, but it can't invent
            # detail that isn't in the source. A higher-resolution source
            # video would look sharper if that matters for your submission.
            scale = sh / frame.height
            new_w, new_h = int(frame.width * scale), sh
            resized = frame.resize((new_w, new_h), Image.LANCZOS)
            canvas_img = Image.new("RGB", (sw, sh), THEME["bg"])
            canvas_img.paste(resized, ((sw - new_w) // 2, 0))
            self._frames.append(ImageTk.PhotoImage(canvas_img))

    def _play_frame(self):
        if self._advanced:
            return
        if self._frame_idx >= len(self._frames):
            self._advance()
            return
        self.label.configure(image=self._frames[self._frame_idx])
        self._frame_idx += 1
        self.after(self._delay_ms, self._play_frame)

    def _advance(self):
        if self._advanced:
            return
        self._advanced = True
        self.on_done()


class IntroLogoScreen(tk.Frame):
    """Shows the project logo with a smooth fade-in from black, then
    holds briefly before moving on. The logo image is scaled to COVER
    the entire screen (its own background fills the frame, cropping
    any overflow) rather than being pasted as a small rectangle on a
    different solid color - that mismatch is what made the logo look
    like a stuck-on sticker instead of a blended background."""

    def __init__(self, master, on_done, hold_ms=1600):
        super().__init__(master, bg=THEME["bg"])
        self.on_done = on_done
        self._hold_ms = hold_ms
        self._advanced = False
        self._add_intro_controls(self._finish)

        self.label = tk.Label(self, bg=THEME["bg"], bd=0, highlightthickness=0)
        self.label.pack(fill="both", expand=True)

        tk.Label(self, text="click or press Enter to skip", bg=THEME["bg"],
                 fg=THEME["fg_dim"], font=("Consolas", 11)).place(relx=0.5, rely=0.97, anchor="s")

        self.bind("<Button-1>", lambda e: self._finish())
        self.bind("<Return>", lambda e: self._finish())
        self.bind("<Escape>", lambda e: self._finish())

        if not os.path.exists(INTRO_LOGO_PATH):
            print(f"[intro] {INTRO_LOGO_PATH} not found next to the script - skipping logo screen.")
            self.after(10, self._finish)
            return

        try:
            self._fade_frames = self._build_fade_frames()
        except Exception as e:
            print(f"[intro] could not load {INTRO_LOGO_PATH}: {e}")
            self.after(10, self._finish)
            return

        self._i = 0
        self._play_fade()


    def _add_intro_controls(self, skip_command):
        bar = tk.Frame(self, bg=THEME["bg_panel"], bd=0)
        bar.place(relx=1.0, x=-18, y=18, anchor="ne")
        tk.Button(bar, text="SKIP", command=skip_command,
                  bg=THEME["bg_panel"], fg=THEME["accent_cyan"],
                  activebackground=THEME["accent_cyan"], activeforeground=THEME["bg"],
                  font=("Consolas", 10, "bold"), relief="solid", bd=1,
                  padx=12, pady=5, cursor="hand2").pack(side="left", padx=(0, 6))
        tk.Button(bar, text="EXIT APP", command=self.master.close_app,
                  bg=THEME["bg_panel"], fg=THEME["accent_red"],
                  activebackground=THEME["accent_red"], activeforeground=THEME["bg"],
                  font=("Consolas", 10, "bold"), relief="solid", bd=1,
                  padx=12, pady=5, cursor="hand2").pack(side="left")

    def _build_fade_frames(self, steps=18):
        sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
        logo = Image.open(INTRO_LOGO_PATH).convert("RGB")

        # COVER-fit: scale so the logo fills the ENTIRE screen, cropping
        # overflow (like CSS background-size:cover). The logo's own
        # background becomes the screen's background, so there's no
        # seam/rectangle edge like a smaller centered paste would have.
        scale = max(sw / logo.width, sh / logo.height)
        new_w, new_h = int(logo.width * scale), int(logo.height * scale)
        logo = logo.resize((new_w, new_h), Image.LANCZOS)
        left, top = (new_w - sw) // 2, (new_h - sh) // 2
        composed = logo.crop((left, top, left + sw, top + sh))

        # Fade in from black (standard cinematic open) rather than from
        # the theme's flat color, since the composed image's edge tones
        # now vary with the logo's own gradient - black fades cleanly
        # against anything.
        black = Image.new("RGB", (sw, sh), (0, 0, 0))
        frames = []
        for i in range(steps + 1):
            alpha = i / steps
            blended = Image.blend(black, composed, alpha)
            frames.append(ImageTk.PhotoImage(blended))
        return frames

    def _play_fade(self):
        if self._advanced:
            return
        if self._i >= len(self._fade_frames):
            self.after(self._hold_ms, self._finish)
            return
        self.label.configure(image=self._fade_frames[self._i])
        self._i += 1
        self.after(35, self._play_fade)

    def _finish(self):
        if self._advanced:
            return
        self._advanced = True
        self.on_done()


class IntroTypingScreen(tk.Frame):
    """Cinematic ChainHawk boot screen: typed title over the generated logo mark."""
    def __init__(self, master, on_done, char_delay_ms=85, hold_ms=900):
        super().__init__(master, bg=THEME["bg"])
        self.on_done = on_done
        self._char_delay = char_delay_ms
        self._hold_ms = hold_ms
        self._advanced = False
        self._add_intro_controls(self._skip)

        sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
        canvas = tk.Canvas(self, highlightthickness=0, bd=0, bg=THEME["bg"])
        canvas.pack(fill="both", expand=True)
        self._canvas = canvas

        # Build a dark background and place the generated hawk as a subtle watermark.
        bg_img = Image.new("RGB", (sw, sh), (6, 11, 20))
        overlay = load_chainhawk_logo(min(int(min(sw, sh) * 0.84), 980), alpha=135)
        ox = (sw - overlay.width) // 2
        oy = (sh - overlay.height) // 2 - 15
        bg_rgba = bg_img.convert("RGBA")
        bg_rgba.alpha_composite(overlay, (ox, oy))
        self._bg_photo = ImageTk.PhotoImage(bg_rgba.convert("RGB"))
        canvas.create_image(0, 0, image=self._bg_photo, anchor="nw")
        canvas.create_rectangle(0, 0, sw, sh, fill="#050a12", stipple="gray25", outline="")

        full_text = APP_NAME.upper()
        font_size = max(54, min(126, int(sw / (len(full_text) * 1.0))))
        self._full_text = full_text
        self._font = ("Segoe UI", font_size, "bold")
        self._text_item = canvas.create_text(sw // 2, sh // 2 - 12, text="", fill="#eefaff", font=self._font)
        canvas.create_text(sw // 2, sh // 2 + font_size * 0.72, text=APP_TAGLINE.upper(),
                           fill=THEME["accent_cyan"], font=("Consolas", max(13, font_size // 6), "bold"))
        canvas.create_text(sw // 2, sh - 38, text="SECURE BOOT  //  PRESS ENTER OR ESC TO SKIP",
                           fill="#5d7489", font=("Consolas", 10, "bold"))
        self.bind("<Button-1>", lambda e: self._skip())
        self.bind("<Return>", lambda e: self._skip())
        self.bind("<Escape>", lambda e: self._skip())
        self._i = 0
        self._type_next()

    def _add_intro_controls(self, skip_command):
        bar = tk.Frame(self, bg="#091522", bd=0, highlightthickness=1, highlightbackground="#17334c")
        bar.place(relx=1.0, x=-18, y=18, anchor="ne")
        tk.Button(bar, text="SKIP", command=skip_command, bg="#091522", fg=THEME["accent_cyan"],
                  activebackground=THEME["accent_cyan"], activeforeground=THEME["bg"],
                  font=("Consolas", 10, "bold"), relief="flat", bd=0, padx=12, pady=6).pack(side="left")
        tk.Button(bar, text="EXIT APP", command=self.master.close_app, bg="#091522", fg=THEME["accent_red"],
                  activebackground=THEME["accent_red"], activeforeground=THEME["bg"],
                  font=("Consolas", 10, "bold"), relief="flat", bd=0, padx=12, pady=6).pack(side="left")

    def _type_next(self):
        if self._advanced: return
        if self._i > len(self._full_text):
            self.after(self._hold_ms, self._finish); return
        cursor = "▌" if (self._i // 2) % 2 == 0 else ""
        self._canvas.itemconfig(self._text_item, text=self._full_text[:self._i] + cursor)
        self._i += 1
        self.after(self._char_delay, self._type_next)

    def _skip(self):
        if self._advanced: return
        self._advanced = True
        self._canvas.itemconfig(self._text_item, text=self._full_text)
        self.after(250, self._finish)

    def _finish(self):
        if not self._advanced: self._advanced = True
        self.on_done()


