# ---------------------------------------------------------------------
# 3. CRYPTOCURRENCY TYPE DETECTOR
# ---------------------------------------------------------------------
def detect_chain(address: str) -> str:
    """Return 'BTC', 'ETH_OR_BSC', or 'UNKNOWN' based on address format."""
    address = address.strip()
    if re.fullmatch(r"^(bc1)[a-z0-9]{25,90}$", address):
        return "BTC"
    if re.fullmatch(r"^[13][a-km-zA-HJ-NP-Z1-9]{25,34}$", address):
        return "BTC"
    if re.fullmatch(r"^0x[a-fA-F0-9]{40}$", address):
        # Same format for ETH and BSC - can't distinguish from address alone.
        # If you need to tell them apart, try both APIs and see which
        # returns data, or let the user pick in the GUI dropdown.
        return "ETH_OR_BSC"
    return "UNKNOWN"


# ---------------------------------------------------------------------
# 2. WALLET ADDRESS TRACKER (real API calls)
# ---------------------------------------------------------------------
def _get_with_retry(url: str, timeout: int = 15, max_retries: int = 4) -> requests.Response:
    """GET with provider-aware diagnostics and respectful 429 backoff."""
    last = None
    for attempt in range(max_retries):
        try:
            resp = requests.get(
                url,
                timeout=timeout,
                headers={"User-Agent": "ChainHawk/6.0 blockchain-osint-client"},
            )
            last = resp
        except requests.RequestException as exc:
            if attempt < max_retries - 1:
                time.sleep(min(2 ** attempt, 8))
                continue
            raise RuntimeError(f"Network request failed: {exc}") from exc

        host = requests.utils.urlparse(url).netloc

        if resp.status_code == 429:
            if attempt < max_retries - 1:
                retry_after = resp.headers.get("Retry-After", "").strip()
                try:
                    wait = max(2, min(int(float(retry_after)), 30)) if retry_after else min(3 * (2 ** attempt), 20)
                except ValueError:
                    wait = min(3 * (2 ** attempt), 20)
                print(f"[rate limit] 429 from {host} - waiting {wait}s before retry")
                time.sleep(wait)
                continue
            detail = resp.text[:300].strip().replace("\n", " ")
            raise RuntimeError(
                f"HTTP 429 Too Many Requests from {host} after {max_retries} attempts. "
                f"Provider rate limit was reached. {detail}"
            )

        if resp.status_code == 402:
            detail = resp.text[:500].strip().replace("\n", " ")
            raise RuntimeError(
                f"HTTP 402 Payment Required from {host}. "
                f"This endpoint rejected the request. Response: {detail or 'no response body'}"
            )

        if resp.status_code >= 400:
            detail = resp.text[:500].strip().replace("\n", " ")
            raise RuntimeError(
                f"HTTP {resp.status_code} from {host}: {detail or resp.reason}"
            )
        return resp

    if last is not None:
        raise RuntimeError(
            f"HTTP {last.status_code} from {requests.utils.urlparse(url).netloc} "
            f"after {max_retries} attempts"
        )
    raise RuntimeError("Request failed without a response")


def _normalize_esplora_tx(tx: dict) -> dict:
    """Convert Esplora's tx shape to ChainHawk's existing BTC graph shape."""
    inputs = []
    for vin in tx.get("vin", []):
        prevout = vin.get("prevout") or {}
        inputs.append({
            "prev_out": {
                "addr": prevout.get("scriptpubkey_address"),
                "value": prevout.get("value", 0),
            }
        })

    outputs = []
    for vout in tx.get("vout", []):
        outputs.append({
            "addr": vout.get("scriptpubkey_address"),
            "value": vout.get("value", 0),
        })

    return {
        "hash": tx.get("txid", ""),
        "tx_index": tx.get("txid", ""),
        "time": (tx.get("status") or {}).get("block_time", 0),
        "inputs": inputs,
        "out": outputs,
        "fee": tx.get("fee", 0),
        "status": tx.get("status", {}),
    }


def _fetch_btc_from_esplora(base_url: str, address: str, limit: int) -> dict:
    """Fetch BTC address stats + recent transaction history from Esplora."""
    base_url = base_url.rstrip("/")
    summary = _get_with_retry(f"{base_url}/address/{address}")
    tx_resp = _get_with_retry(f"{base_url}/address/{address}/txs")

    stats = summary.json()
    raw_txs = tx_resp.json()
    if not isinstance(raw_txs, list):
        raise RuntimeError(f"Unexpected BTC API response from {base_url}")

    chain_stats = stats.get("chain_stats", {}) or {}
    mempool_stats = stats.get("mempool_stats", {}) or {}

    funded = int(chain_stats.get("funded_txo_sum", 0) or 0) + int(mempool_stats.get("funded_txo_sum", 0) or 0)
    spent = int(chain_stats.get("spent_txo_sum", 0) or 0) + int(mempool_stats.get("spent_txo_sum", 0) or 0)
    n_tx = int(chain_stats.get("tx_count", 0) or 0) + int(mempool_stats.get("tx_count", 0) or 0)

    return {
        "balance": (funded - spent) / 1e8,
        "total_received": funded / 1e8,
        "total_sent": spent / 1e8,
        "n_tx": n_tx,
        "txs": [_normalize_esplora_tx(tx) for tx in raw_txs[:limit]],
        "provider": base_url,
    }


def fetch_btc_transactions(address: str, limit: int = 50) -> dict:
    """Fetch BTC data using Esplora, with a second provider as fallback."""
    errors = []
    for provider in (BTC_API_BASE, BTC_API_FALLBACK):
        if not provider:
            continue
        try:
            return _fetch_btc_from_esplora(provider, address, limit)
        except Exception as exc:
            errors.append(f"{provider}: {exc}")
            print(f"[BTC provider] {provider} failed: {exc}")

    raise RuntimeError(
        "BTC transaction retrieval failed. ChainHawk no longer uses "
        "blockchain.info/rawaddr. Tried the configured Esplora providers. "
        + " | ".join(errors)
    )

def fetch_eth_transactions(address: str, limit: int = 50) -> dict:
    """Pull recent ETH transactions through Etherscan API V2 (Ethereum mainnet)."""
    if not ETHERSCAN_API_KEY or ETHERSCAN_API_KEY == "YOUR_ETHERSCAN_API_KEY":
        raise RuntimeError(
            "Ethereum API is not configured. Set ETHERSCAN_API_KEY to an active Etherscan API key."
        )

    url = (
        "https://api.etherscan.io/v2/api"
        f"?chainid=1&module=account&action=txlist&address={address}"
        f"&startblock=0&endblock=99999999&sort=desc"
        f"&apikey={ETHERSCAN_API_KEY}"
    )
    resp = _get_with_retry(url)
    data = resp.json()
    result = data.get("result", [])

    # Etherscan returns HTTP 200 even for API-level errors, so
    # raise_for_status() above never catches this. On error, "result"
    # is a STRING message (e.g. "Missing/Invalid API Key") instead of
    # a list of transactions - check for that explicitly instead of
    # blindly slicing/iterating it (which crashes elsewhere with a
    # confusing 'str has no attribute get' error).
    if isinstance(result, str):
        hint = " - check that ETHERSCAN_API_KEY is set to a real key" \
            if ETHERSCAN_API_KEY in ("YOUR_ETHERSCAN_API_KEY", "", None) else ""
        raise RuntimeError(f"Etherscan API error: {result}{hint}")

    txs = result[:limit]
    return {"n_tx": len(txs), "txs": txs}


def trace_wallet(address: str) -> dict:
    """Single entry point: detect chain, fetch data, return normalized result."""
    chain = detect_chain(address)
    if chain == "BTC":
        return {"chain": "BTC", **fetch_btc_transactions(address)}
    elif chain == "ETH_OR_BSC":
        return {"chain": "ETH", **fetch_eth_transactions(address)}
    else:
        raise ValueError(f"Unrecognized address format: {address}")


# ---------------------------------------------------------------------
# 4. ADDRESS REPUTATION CHECKER
# ---------------------------------------------------------------------
def check_btc_reputation(address: str) -> dict:
    """
    Checks a BTC address against a LOCAL sanctioned-address list
    instead of a live API - BitcoinWhosWho's free tier turned out to
    allow only 1 call/day, which is useless for an interactive tool.

    This uses addresses from the US Treasury OFAC SDN list (the same
    list real compliance/forensics tools check against), which is
    actually a better fit for a ransomware-tracing project than a
    generic scam database: OFAC specifically sanctions ransomware
    operators' payment addresses. Checking locally means zero rate
    limits and instant results.

    The list below ships with a small set of real, publicly-reported
    OFAC-sanctioned addresses as a working starter. For the full,
    current list: download/parse sdn_advanced.xml from
    https://sanctionslist.ofac.treas.gov/, or use the maintained
    extractor at https://github.com/0xB10C/ofac-sanctioned-digital-currency-addresses
    and save the BTC addresses (one per line) into a local file named
    ofac_btc_addresses.txt next to this script - it will be picked up
    automatically and merged with the starter set below.
    """
    sanctioned = _load_sanctioned_btc_addresses()
    flagged = address in sanctioned
    return {"flagged": flagged, "source": "local OFAC sanctions list", "list_size": len(sanctioned)}


_SANCTIONED_BTC_STARTER_SET = {
    # A small set of real, publicly-reported OFAC SDN-listed Bitcoin
    # addresses (news-verified examples), included so the reputation
    # check has something real to match against out of the box.
    "1JPfVv5cWRLx1js9NWxg46dG2CGbeRz4th",  # OFAC-sanctioned (Hebei Atun Trading Co., 2023 designation)
}


def _load_sanctioned_btc_addresses() -> set:
    """Loads the starter set, plus any addresses from a local
    ofac_btc_addresses.txt file if present (one address per line)."""
    addresses = set(_SANCTIONED_BTC_STARTER_SET)
    try:
        with open("ofac_btc_addresses.txt", "r") as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#"):
                    addresses.add(line)
    except FileNotFoundError:
        pass  # fine - just use the starter set
    return addresses


def _extract_flagged_from_payload(data):
    """Best-effort normalization for vendor-specific AML/reputation payloads."""
    if not isinstance(data, dict):
        return False, None
    text = str(data).lower()
    risk_words = ("scam", "ransomware", "fraud", "blocked", "sanction", "blacklist", "high risk", "malicious")
    flagged = any(w in text for w in risk_words)
    return flagged, data.get("risk_score") or data.get("score")


def check_cryptoscamdb(address: str) -> dict:
    try:
        resp = requests.get(f"{CRYPTO_SCAM_DB_URL.rstrip('/')}/{address}", timeout=12)
        resp.raise_for_status()
        data = resp.json()
        flagged = bool(data.get("success") and data.get("result", {}).get("status") == "blocked")
        return {"provider": "CryptoScamDB", "configured": True, "flagged": flagged, "raw": data}
    except Exception as e:
        return {"provider": "CryptoScamDB", "configured": True, "flagged": False, "error": str(e)}


def check_chainabuse(address: str, chain: str) -> dict:
    if not CHAINABUSE_API_KEY:
        return {"provider": "Chainabuse", "configured": False, "flagged": False, "error": "CHAINABUSE_API_KEY is not configured"}
    try:
        headers = {"Accept": "application/json"}
        params = {"address": address, "chain": chain.lower()}
        resp = requests.get("https://api.chainabuse.com/v0/reports", params=params, headers=headers, auth=(CHAINABUSE_API_KEY, CHAINABUSE_API_KEY), timeout=12)
        resp.raise_for_status()
        data = resp.json()
        reports = data.get("reports", data.get("data", []))
        if not isinstance(reports, list):
            reports = []
        flagged = len(reports) > 0
        return {"provider": "Chainabuse", "configured": True, "flagged": flagged, "reports": reports, "raw": data}
    except Exception as e:
        return {"provider": "Chainabuse", "configured": True, "flagged": False, "error": str(e)}


def check_reputation(address: str) -> dict:
    """Run the three requested reputation sources concurrently.

    A provider being unavailable is kept separate from a clean result; a
    missing API key must never be presented to an analyst as "CLEAR".
    """
    chain = detect_chain(address)
    checks = {
        "CryptoScamDB": (lambda: check_cryptoscamdb(address)),
        "Chainabuse": (lambda: check_chainabuse(address, chain)),
    }
    results = {}
    with ThreadPoolExecutor(max_workers=2) as pool:
        futures = {pool.submit(fn): name for name, fn in checks.items()}
        for future in as_completed(futures):
            name = futures[future]
            try:
                results[name] = future.result()
            except Exception as e:
                results[name] = {"provider": name, "configured": True, "flagged": False, "error": str(e)}

    flagged_sources = [name for name, r in results.items() if r.get("flagged")]
    configured = [name for name, r in results.items() if r.get("configured")]
    errors = {name: r.get("error") for name, r in results.items() if r.get("error")}
    return {
        "flagged": bool(flagged_sources),
        "flagged_sources": flagged_sources,
        "configured_sources": configured,
        "errors": errors,
        "sources": results,
    }


# ---------------------------------------------------------------------
# 5. TRANSACTION VISUALIZATION DASHBOARD
# ---------------------------------------------------------------------
def extract_counterparties(address: str, chain: str, txs: list, max_counterparties: int = 10) -> list:
    """
    Turn raw transaction records into a list of (counterparty_address,
    direction, value) tuples - one entry per UNIQUE counterparty address.

    Capped by number of *distinct* addresses found (not raw tx count),
    since a busy address can have hundreds of transactions with the same
    handful of counterparties (e.g. exchange consolidation wallets) -
    capping by tx count alone can produce a graph with only 1 node.
    """
    seen = {}
    for tx in txs:
        if len(seen) >= max_counterparties:
            break

        if chain == "BTC":
            # blockchain.info format: tx has "inputs" (each with prev_out.addr)
            # and "out" (each with addr + value in satoshis)
            for inp in tx.get("inputs", []):
                if len(seen) >= max_counterparties:
                    break
                prev = inp.get("prev_out", {})
                addr = prev.get("addr")
                if addr and addr != address and addr not in seen:
                    seen[addr] = ("in", prev.get("value", 0) / 1e8)
            for out in tx.get("out", []):
                if len(seen) >= max_counterparties:
                    break
                addr = out.get("addr")
                if addr and addr != address and addr not in seen:
                    seen[addr] = ("out", out.get("value", 0) / 1e8)
        else:
            # Etherscan format: tx has "from" and "to" directly, value in wei
            frm = tx.get("from", "")
            to = tx.get("to", "")
            value = int(tx.get("value", 0)) / 1e18
            if frm.lower() == address.lower() and to and to not in seen:
                seen[to] = ("out", value)
            elif to.lower() == address.lower() and frm and frm not in seen:
                seen[frm] = ("in", value)

    return [(addr, direction, value) for addr, (direction, value) in seen.items()]


def build_trace_graph(address: str, trace_result: dict) -> nx.DiGraph:
    """
    Build a directed graph: the searched address is the 'source' node,
    every counterparty it transacted with becomes a 'hop' node.
    Edge direction follows where the money actually moved.
    """
    G = nx.DiGraph()
    G.add_node(address, kind="source", hop=0)

    edges = extract_counterparties(address, trace_result["chain"], trace_result.get("txs", []))
    for counterparty, direction, value in edges:
        G.add_node(counterparty, kind="hop", hop=1)
        if direction == "out":
            G.add_edge(address, counterparty, value=value)
        else:
            G.add_edge(counterparty, address, value=value)
    return G


def trace_multi_hop(
    address: str,
    chain: str,
    initial_txs: list = None,
    max_depth: int = 2,
    max_counterparties_per_hop: int = 4,
    max_total_nodes: int = 25,
    delay_seconds: float = 1.0,
    log_fn=None,
) -> nx.DiGraph:
    """
    Recursively trace an address's counterparties, and THEIR
    counterparties, up to max_depth hops - producing a chain graph like
    the prototype's Victim -> Attacker -> Mixer demo, instead of a
    single-level star.

    SAFETY LIMITS (important - this makes real, repeated API calls):
    - max_depth: how many hops deep to follow (2 is a good default;
      each extra level multiplies the number of API calls, so avoid
      going much higher without raising the API rate-limit handling)
    - max_counterparties_per_hop: branches per node
    - max_total_nodes: hard ceiling on the whole graph, in case of a
      busy hub address that would otherwise explode combinatorially
    - delay_seconds: politeness delay between calls so you don't get
      rate-limited (Etherscan free tier allows ~5 calls/sec)

    log_fn: optional callback(str) to report progress back to the GUI
    while this runs (since it can take a while).
    """
    def _log(msg):
        if log_fn:
            log_fn(msg)

    G = nx.DiGraph()
    G.add_node(address, kind="source", hop=0)
    visited = {address}
    frontier = [(address, 0)]

    while frontier:
        current, hop = frontier.pop(0)
        if hop >= max_depth or len(visited) >= max_total_nodes:
            continue

        _log(f"Hop {hop}: fetching transactions for {current[:10]}...")
        try:
            if chain == "BTC":
                if current == address and initial_txs is not None:
                    txs = initial_txs
                else:
                    txs = fetch_btc_transactions(current, limit=30).get("txs", [])
            else:
                if current == address and initial_txs is not None:
                    txs = initial_txs
                else:
                    txs = fetch_eth_transactions(current, limit=30).get("txs", [])
        except Exception as e:
            _log(f"  (skipped {current[:10]}...: {type(e).__name__}: {e})")
            continue

        edges = extract_counterparties(current, chain, txs, max_counterparties=max_counterparties_per_hop)
        for counterparty, direction, value in edges:
            if len(visited) >= max_total_nodes:
                break

            if counterparty not in G.nodes:
                G.add_node(counterparty, kind="hop", hop=hop + 1)
            if direction == "out":
                G.add_edge(current, counterparty, value=value)
            else:
                G.add_edge(counterparty, current, value=value)

            if counterparty not in visited:
                visited.add(counterparty)
                frontier.append((counterparty, hop + 1))

        time.sleep(delay_seconds)

    _log(f"Multi-hop trace complete: {G.number_of_nodes()} nodes, {G.number_of_edges()} edges.")
    return G



# ---------------------------------------------------------------------
# 6. ALERT SYSTEM FOR NEW TRANSACTIONS (simple polling version)
# ---------------------------------------------------------------------
class TransactionWatcher:
    """Polls the target wallet and raises alerts when unseen transaction IDs appear."""
    def __init__(self, address: str, on_new_tx, interval_seconds: int = ALERT_INTERVAL_SECONDS):
        self.address = address
        self.on_new_tx = on_new_tx
        self.interval = max(15, interval_seconds)
        self._known_ids = set()
        self._stop = threading.Event()

    def start(self):
        threading.Thread(target=self._loop, daemon=True, name="ChainHawkWatcher").start()

    def stop(self):
        self._stop.set()

    @staticmethod
    def _tx_id(tx, chain):
        return tx.get("hash") or tx.get("txid") or tx.get("blockhash")

    def _loop(self):
        first = True
        while not self._stop.is_set():
            try:
                result = trace_wallet(self.address)
                txs = result.get("txs", []) or []
                current_ids = {self._tx_id(tx, result.get("chain")) for tx in txs}
                current_ids.discard(None)
                if first:
                    self._known_ids = current_ids
                    first = False
                else:
                    new_ids = list(current_ids - self._known_ids)
                    if new_ids:
                        self.on_new_tx(self.address, len(new_ids), new_ids[:10], result.get("chain", ""))
                    self._known_ids.update(current_ids)
            except Exception as e:
                print(f"[watcher] error checking {self.address}: {e}")
            self._stop.wait(self.interval)


